package com.loja.orderservice.service;

import com.loja.orderservice.client.TransLogClient;
import com.loja.orderservice.dto.CustomerDTO;
import com.loja.orderservice.dto.OrderItemDTO;
import com.loja.orderservice.dto.OrderRequestDTO;
import com.loja.orderservice.entity.*;
import com.loja.orderservice.repository.ProductRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class PricingServiceTest {
    @Mock
    private ProductRepository productRepository;

    @Mock
    private TransLogClient transLogClient;

    private PricingService pricingService;

    @BeforeEach
    void setUp() {
        pricingService = new PricingService(productRepository, transLogClient);
    }

    @Test
    void testCalculateSummaryBasic() throws TransLogClient.TransLogException {
        OrderRequestDTO request = createBasicRequest();

        Product cam001 = new Product("CAM-001", "Camiseta básica", new BigDecimal("79.90"), new BigDecimal("0.30"), 50, false);
        Product ten001 = new Product("TEN-001", "Tênis corrida", new BigDecimal("249.90"), new BigDecimal("1.20"), 10, false);

        when(productRepository.findById("CAM-001")).thenReturn(Optional.of(cam001));
        when(productRepository.findById("TEN-001")).thenReturn(Optional.of(ten001));
        when(transLogClient.getQuote(anyString(), anyInt(), anyString()))
            .thenReturn(new TransLogClient.TransLogQuote(3310, 41));

        OrderSummary summary = pricingService.calculateSummary(request);

        assertNotNull(summary);
        assertEquals(new BigDecimal("409.70"), summary.getProductsSubtotal());
        assertTrue(summary.getFinalTotal().compareTo(BigDecimal.ZERO) > 0);
    }

    private OrderRequestDTO createBasicRequest() {
        OrderRequestDTO request = new OrderRequestDTO();
        request.setCustomer(new CustomerDTO("12345678909", "test@example.com"));
        request.setItems(Arrays.asList(
            new OrderItemDTO("CAM-001", 2),
            new OrderItemDTO("TEN-001", 1)
        ));
        request.setZipCode("01310100");
        request.setRegion(Region.SOUTHEAST);
        request.setShippingMethod(ShippingMethod.EXPRESS);
        request.setCoupon(null);
        request.setPaymentMethod(PaymentMethod.PIX);
        request.setInstallments(1);
        request.setClubTier(ClubTier.BRONZE);
        return request;
    }
}

